#pragma once
// Combat sounds (sub-project 7 spec, "Presentation"): the window host plays the combat log's
// events through AudioSystem, beside the footsteps (LiveConfig::footsteps covers both; ohao_game
// --mute silences them). Sounds are assets/audio/weapons/<name>.wav, OHAO's own, generated by
// tools/audio/make_weapons.py. Which sounds an event plays is soundsFor; headless hosts play none.
#include "audio/audio_system.hpp"
#include "ecs/combat.hpp"
#include "ecs/world.hpp"

#include <cstdint>
#include <filesystem>
#include <map>
#include <string>
#include <vector>

namespace ohao::runtime {

// The sounds a combat event plays, by name: the player's round "fire", anyone else's
// "enemy_fire"; a hit "impact_<surface>"; damage to the player "hurt"; a death "death"; the
// player's reload "reload", after "empty" when the magazine ran dry. Nothing else plays.
[[nodiscard]] std::vector<std::string> soundsFor(const ecs::CombatEvent& event, uint64_t playerId);

class CombatSounds {
public:
    // The default audio device and the sounds in `root`/assets/audio/weapons. False when there is
    // no audio device; update then does nothing.
    bool initialize(const std::filesystem::path& root);
    // Plays what the combat log holds since the last call (the first call starts at its end).
    // Call once per frame, after the frame's steps.
    void update(ecs::World& world);
    [[nodiscard]] uint64_t played() const noexcept { return m_played; }
    [[nodiscard]] std::size_t sounds() const noexcept { return m_files.size(); }
    void setVolume(float volume) { m_audio.setMasterVolume(volume); }

private:
    AudioSystem m_audio;
    std::map<std::string, std::string, std::less<>> m_files;   // name -> path
    uint64_t m_cursor{0};
    bool m_started{false};
    uint64_t m_played{0};
};

} // namespace ohao::runtime
